  2761  static int WGET_GCC_NONNULL((2)) parse_command_line(int argc, const char **argv)
  2762  {
  2763          static short shortcut_to_option[128];
  2764          const char *first_arg = NULL;
  2765          int n, rc;
  2766
  2767          // init the short option lookup table
  2768          if (!shortcut_to_option[0]) {
  2769                  for (short it = 0; it < (short) countof(options); it++) {
  2770                          if (options[it].short_name > 0)
  2771                                  shortcut_to_option[(unsigned char)options[it].short_name] = it + 1;
  2772                  }
  2773          }
  2774
  2775          // I like the idea of getopt() but not it's implementation (e.g. global variables).
  2776          // Therefore I implement my own getopt() behavior.
  2777          for (n = 1; n < argc && first_arg != argv[n]; n++) {
  2778                  const char *argp = argv[n];
  2779
  2780                  if (argp[0] != '-') {
  2781                          // Move args behind options to allow mixed args/options like getopt().
  2782                          // In the end, the order of the args is as before.
  2783                          const char *cur = argv[n];
  2784                          for (int it = n; it < argc - 1; it++)
  2785                                  argv[it] = argv[it + 1];
  2786                          argv[argc - 1] = cur;
  2787
  2788                          // Once we see the first arg again, we are done
  2789                          if (!first_arg)
  2790                                  first_arg = cur;
  2791
  2792                          n--;
  2793                          continue;
  2794                  }
  2795
  2796                  if (argp[1] == '-') {
  2797                          // long option
  2798                          if (argp[2] == 0)
  2799                                  return n + 1;
  2800
  2801                          if ((rc = set_long_option(argp + 2, n < argc - 1 ? argv[n+1] : NULL, 0)) < 0)
  2802                                  return rc;
  2803
  2804                          n += rc;
  2805
  2806                  } else if (argp[1]) {
  2807                          // short option(s)
  2808                          for (int pos = 1; argp[pos]; pos++) {
  2809                                  option_t opt;
  2810                                  int idx;
  2811
  2812                                  if (c_isalnum(argp[pos]) && (idx = shortcut_to_option[(unsigned char)argp[pos]])) {
  2813                                          opt = &options[idx - 1];
  2814                                          // info_printf("opt=%p [%c]\n",(void *)opt,argp[pos]);
  2815                                          // info_printf("name=%s\n",opt->long_name);
  2816                                          if (opt->args > 0) {
  2817                                                  const char *val;
  2818
  2819                                                  if (!argp[pos + 1] && argc <= n + opt->args) {
  2820                                                          error_printf(_("Missing argument(s) for option '-%c'\n"), argp[pos]);
  2821                                                          return -1;
  2822                                                  }
  2823                                                  val = argp[pos + 1] ? argp + pos + 1 : argv[++n];
  2824                                                  if ((rc = opt->parser(opt, val, 0)) < 0)
  2825                                                          return rc;
  2826                                                  n += rc;
  2827                                                  break;
  2828                                          } else {//if (opt->args == 0)
  2829                                                  if ((rc = opt->parser(opt, NULL, 0)) < 0)
  2830                                                          return rc;
  2831                                          }
  2832  /*                                      else {
  2833                                                  const char *val;
  2834                                                  val = argp[pos + 1] ? argp + pos + 1 : NULL;
  2835                                                  n += opt->parser(opt, val);
  2836                                                  break;
  2837                                          }
  2838  */
  2839                                  } else {
  2840                                          error_printf(_("Unknown option '-%c'\n"), argp[pos]);
  2841                                          return -1;
  2842                                  }
  2843                          }
  2844                  }
  2845          }
  2846
  2847          return n;
  2848  }
